CREATE TABLE IF NOT EXISTS extension_registry (
  id text PRIMARY KEY,
  name text NOT NULL,
  description text,
  author text NOT NULL,
  author_email text,
  author_url text,
  version text NOT NULL,
  type text NOT NULL CHECK (type IN ('app', 'channel', 'tool', 'integration')),
  category text,
  tags text,
  icon_url text,
  screenshot_urls text,
  download_url text NOT NULL,
  homepage_url text,
  repository_url text,
  license text DEFAULT 'MIT',
  min_agent_version text,
  permissions text,
  dependencies text,
  install_count bigint DEFAULT 0,
  rating_avg double precision DEFAULT 0.0,
  rating_count bigint DEFAULT 0,
  featured integer DEFAULT 0,
  verified integer DEFAULT 0,
  status text DEFAULT 'active' CHECK (status IN ('active', 'deprecated', 'removed')),
  published_at timestamptz DEFAULT now(),
  updated_at timestamptz DEFAULT now(),
  created_at timestamptz DEFAULT now()
);

CREATE TABLE IF NOT EXISTS extension_versions (
  id text PRIMARY KEY,
  extension_id text NOT NULL,
  version text NOT NULL,
  changelog text,
  download_url text NOT NULL,
  min_agent_version text,
  breaking_changes integer DEFAULT 0,
  release_date timestamptz DEFAULT now(),
  created_at timestamptz DEFAULT now(),
  FOREIGN KEY (extension_id) REFERENCES extension_registry (id) ON DELETE CASCADE,
  UNIQUE (extension_id, version)
);

CREATE TABLE IF NOT EXISTS extension_installations (
  id text PRIMARY KEY,
  extension_id text NOT NULL,
  user_id text NOT NULL,
  installed_version text NOT NULL,
  install_date timestamptz DEFAULT now(),
  last_update_check timestamptz,
  auto_update integer DEFAULT 1,
  created_at timestamptz DEFAULT now(),
  updated_at timestamptz DEFAULT now(),
  UNIQUE (extension_id, user_id)
);

CREATE TABLE IF NOT EXISTS extension_reviews (
  id text PRIMARY KEY,
  extension_id text NOT NULL,
  user_id text NOT NULL,
  rating bigint NOT NULL CHECK (rating >= 1 AND rating <= 5),
  review_title text,
  review_text text,
  helpful_count bigint DEFAULT 0,
  version text,
  created_at timestamptz DEFAULT now(),
  updated_at timestamptz DEFAULT now(),
  FOREIGN KEY (extension_id) REFERENCES extension_registry (id) ON DELETE CASCADE,
  UNIQUE (extension_id, user_id)
);

CREATE TABLE IF NOT EXISTS extension_update_queue (
  id text PRIMARY KEY,
  extension_id text NOT NULL,
  user_id text NOT NULL,
  current_version text NOT NULL,
  target_version text NOT NULL,
  status text DEFAULT 'pending' CHECK (status IN ('pending', 'in_progress', 'completed', 'failed')),
  error_message text,
  scheduled_at timestamptz DEFAULT now(),
  completed_at timestamptz,
  created_at timestamptz DEFAULT now()
);

